using LigaVolley.Domain.CompetitionRosters;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace LigaVolley.Infrastructure.Persistence.Configurations;
internal sealed class CompetitionRosterConfiguration:IEntityTypeConfiguration<CompetitionRoster>{public void Configure(EntityTypeBuilder<CompetitionRoster>b){b.ToTable("COMPETITION_ROSTER","dbo",t=>t.HasCheckConstraint("CK_COMPETITION_ROSTER_status","[status] IN ('DRAFT','ACTIVE','CLOSED')"));b.HasKey(x=>x.CompetitionRosterId).HasName("PK_COMPETITION_ROSTER");b.Property(x=>x.CompetitionRosterId).HasColumnName("competition_roster_id").UseIdentityColumn();b.Property(x=>x.TeamEntryId).HasColumnName("team_entry_id");b.Property(x=>x.Status).AsSql("status",10);b.HasOne(x=>x.TeamEntry).WithOne().HasForeignKey<CompetitionRoster>(x=>x.TeamEntryId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_COMPETITION_ROSTER_TEAM_ENTRY");b.HasIndex(x=>x.TeamEntryId).IsUnique().HasDatabaseName("UQ_COMPETITION_ROSTER_team_entry");}}
internal sealed class CompetitionRosterPlayerConfiguration:IEntityTypeConfiguration<CompetitionRosterPlayer>{public void Configure(EntityTypeBuilder<CompetitionRosterPlayer>b){b.ToTable("COMPETITION_ROSTER_PLAYER","dbo",t=>{t.HasCheckConstraint("CK_COMPETITION_ROSTER_PLAYER_status","[status] IN ('ACTIVE','INACTIVE')");t.HasCheckConstraint("CK_COMPETITION_ROSTER_PLAYER_role","[player_role] IN ('SETTER','OUTSIDE_HITTER','MIDDLE_BLOCKER','OPPOSITE','LIBERO')");});b.HasKey(x=>x.CompetitionRosterPlayerId).HasName("PK_COMPETITION_ROSTER_PLAYER");b.Property(x=>x.CompetitionRosterPlayerId).HasColumnName("competition_roster_player_id").UseIdentityColumn();b.Property(x=>x.CompetitionRosterId).HasColumnName("competition_roster_id");b.Property(x=>x.PlayerId).HasColumnName("player_id");b.Property(x=>x.JerseyNumber).HasColumnName("jersey_number").HasColumnType("smallint");b.Property(x=>x.Role).AsSql("player_role",30);b.Property(x=>x.Status).AsSql("status",10);b.HasOne(x=>x.CompetitionRoster).WithMany(x=>x.Players).HasForeignKey(x=>x.CompetitionRosterId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_COMPETITION_ROSTER_PLAYER_ROSTER");b.HasOne(x=>x.Player).WithMany().HasForeignKey(x=>x.PlayerId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_COMPETITION_ROSTER_PLAYER_PLAYER");b.HasIndex(x=>new{x.CompetitionRosterId,x.PlayerId}).IsUnique().HasDatabaseName("UQ_COMPETITION_ROSTER_PLAYER_player");b.HasIndex(x=>new{x.CompetitionRosterId,x.JerseyNumber}).IsUnique().HasFilter("[status] = 'ACTIVE' AND [jersey_number] IS NOT NULL").HasDatabaseName("UX_COMPETITION_ROSTER_PLAYER_active_jersey");b.HasIndex(x=>new{x.CompetitionRosterId,x.Status,x.Role}).HasDatabaseName("IX_COMPETITION_ROSTER_PLAYER_limits");}}
internal sealed class CompetitionRosterStaffConfiguration:IEntityTypeConfiguration<CompetitionRosterStaff>{public void Configure(EntityTypeBuilder<CompetitionRosterStaff>b){b.ToTable("COMPETITION_ROSTER_STAFF","dbo",t=>t.HasCheckConstraint("CK_COMPETITION_ROSTER_STAFF_status","[status] IN ('ACTIVE','INACTIVE')"));b.HasKey(x=>x.CompetitionRosterStaffId).HasName("PK_COMPETITION_ROSTER_STAFF");b.Property(x=>x.CompetitionRosterStaffId).HasColumnName("competition_roster_staff_id").UseIdentityColumn();b.Property(x=>x.CompetitionRosterId).HasColumnName("competition_roster_id");b.Property(x=>x.CoachId).HasColumnName("coach_id");b.Property(x=>x.Status).AsSql("status",10);b.HasOne(x=>x.CompetitionRoster).WithMany(x=>x.Staff).HasForeignKey(x=>x.CompetitionRosterId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_COMPETITION_ROSTER_STAFF_ROSTER");b.HasOne(x=>x.Coach).WithMany().HasForeignKey(x=>x.CoachId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_COMPETITION_ROSTER_STAFF_COACH");b.HasIndex(x=>new{x.CompetitionRosterId,x.CoachId}).IsUnique().HasDatabaseName("UQ_COMPETITION_ROSTER_STAFF_coach");b.HasIndex(x=>new{x.CompetitionRosterId,x.Status}).HasDatabaseName("IX_COMPETITION_ROSTER_STAFF_limit");}}
